"""Import legacy epoch metrics into MLflow, retain the best bundle and prune history."""
import argparse
import json
import os
import re
import shutil
from pathlib import Path
from filelock import FileLock
import mlflow
from .checkpoint import champion_rank
from .config import Config
from .inference import QueryParser, resolve_checkpoint
from .tracking import tracking_run


def migrate(run_path, tracking_uri=None, experiment='person-query-parser'):
    """Only handle the exact legacy layout generated by this project's trainer."""
    root = Path(run_path).resolve()
    with FileLock(str(root.parent / f'.{root.name}.training.lock'), timeout=0):
        if (root / 'champion').exists():
            raise ValueError('Run already contains champion; migration is not needed')
        selected = resolve_checkpoint(root).resolve()
        if selected.parent != root:
            raise ValueError('Legacy best must be a bundle inside this run')
        epochs, states = [], []
        for path in root.iterdir():
            if path.is_symlink():
                raise ValueError(f'Refusing to prune a symlink: {path}')
            if path.is_file() and path.name in ('best.txt', 'last.txt'):
                continue
            if path.is_dir() and re.fullmatch(r'epoch-\d+', path.name):
                manifest = json.loads((path / 'manifest.json').read_text())
                if manifest.get('fine_tuned') is not True or not (path / 'model.safetensors').is_file():
                    raise ValueError(f'Incomplete legacy bundle: {path}')
                champion_rank(manifest['metrics'])
                epochs.append((int(path.name.split('-')[1]), path, manifest))
            elif path.is_dir() and re.fullmatch(r'state-\d+', path.name):
                # Validate this is a training state before allowing its removal.
                state = json.loads((path / 'progress.json').read_text())
                if not {'config', 'next_epoch', 'global_step'} <= state.keys():
                    raise ValueError(f'Invalid legacy training state: {path}')
                states.append(path)
            else:
                raise ValueError(f'Unrecognized run entry; nothing pruned: {path}')
        epochs.sort()
        best_epoch, best_path, manifest = max(epochs, key=lambda row: champion_rank(row[2]['metrics']))
        if best_path != selected:
            raise ValueError('best.txt disagrees with saved metrics; review this run before migration')
        # Verify actual weights/tokenizer can load before deleting any older model.
        loaded = QueryParser.from_checkpoint(selected)
        del loaded
        config = Config.load(selected / 'config.json')
        progress = root / f'state-{best_epoch}' / 'progress.json'
        state = json.loads(progress.read_text()) if progress.is_file() else {}
        signature = state.get('signature', {'legacy_source': str(root)})
        with tracking_run(config, signature, root, tracking_uri, experiment,
                          root.name + '-legacy-import') as run_id:
            mlflow.set_tag('historical_import', 'true')
            for epoch, _, record in epochs:
                mlflow.log_metrics(record['metrics'], step=epoch, synchronous=True)
            mlflow.set_tag('champion_epoch', str(best_epoch))
            mlflow.log_metrics({'champion_exact_match_accuracy': manifest['metrics']['exact_match_accuracy'],
                                'champion_validation_loss': manifest['metrics']['validation_loss']},
                               step=best_epoch, synchronous=True)
            manifest['training'] = {'epoch': best_epoch, 'mlflow_run_id': run_id,
                                    'dataset_signature': signature, 'legacy_import': True}
            # Persist history successfully before touching any legacy checkpoint.
            mlflow.log_dict(manifest, 'champion.json')
            champion = root / 'champion'
            os.replace(selected, champion)
            temporary = champion / '.manifest.tmp'
            temporary.write_text(json.dumps(manifest, indent=2))
            os.replace(temporary, champion / 'manifest.json')
            for _, path, _ in epochs:
                if path != selected:
                    shutil.rmtree(path)
            for path in states:
                shutil.rmtree(path)
            for name in ('best.txt', 'last.txt'):
                (root / name).unlink(missing_ok=True)
            mlflow.set_tag('legacy_pruned', 'true')
            return run_id


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--run', required=True, help='Legacy run to convert; other epochs/states will be removed')
    parser.add_argument('--tracking-uri')
    parser.add_argument('--experiment', default='person-query-parser')
    args = parser.parse_args()
    print(json.dumps({'mlflow_run_id': migrate(args.run, args.tracking_uri, args.experiment),
                      'champion': str(Path(args.run) / 'champion')}))


if __name__ == '__main__':
    main()
